#!/usr/bin/env bash
# Checks src/mlx_serve/ (generated by scripts/prepare.sh) against the reviewed tree's hash in scripts/mlx_serve.sha256.
# prepare.sh runs it last and build.zig runs it first, so no build goes on with a stale or edited copy.
set -euo pipefail
here="$(cd "$(dirname "$0")/.." && pwd)"
dst="$here/src/mlx_serve"
[ -d "$dst" ] || { echo "src/mlx_serve is not generated: run scripts/prepare.sh" >&2; exit 1; }
got="$(cd "$dst" && find . -type f ! -name .generated | LC_ALL=C sort | xargs shasum -a 256 | shasum -a 256 | cut -d' ' -f1)"
want="$(tr -d '[:space:]' < "$here/scripts/mlx_serve.sha256")"
if [ "$got" != "$want" ]; then
  echo "src/mlx_serve hashes to $got, not the reviewed $want (scripts/mlx_serve.sha256): re-sync (delete" >&2
  echo "src/mlx_serve, run scripts/prepare.sh, review what it wrote) and commit the new hash" >&2
  exit 1
fi
